Templates.Starter:
{{/* @dot github.com/donseba/go-webthings/modules/events.ListView */}}
<main id="content">
    <h1>{{.Title}}</h1>

    <nav>
        {{if .Past}}<a href="{{.UpcomingURL}}">Upcoming</a>{{else}}<a href="{{.PastURL}}">Past events</a>{{end}}
    </nav>

    {{range .Events}}
        <article>
            {{with .ImageURL}}<img src="{{image . "400x300 crop"}}" alt="">{{end}}
            <h2><a href="{{.URL}}">{{.Title}}</a></h2>
            <p>
                <time datetime="{{.Start.Format "2006-01-02T15:04:05Z07:00"}}">{{with .When}}{{if .AllDay}}{{dateRange .Start .End "full"}}{{else if .SameDay}}{{date .Start "full"}} · {{timeRange .Start .End}}{{else}}{{date .Start "full"}}, {{time .Start}} – {{date .End "full"}}, {{time .End}}{{end}}{{end}}</time>
                {{with .Location}} · {{.}}{{end}}
            </p>
            {{with .Summary}}<p>{{.}}</p>{{end}}
        </article>
    {{else}}
        <p>No events.</p>
    {{end}}
</main>

{{/* @dot github.com/donseba/go-webthings/modules/events.Event */}}
<main id="content">
    <article>
        <h1>{{.Title}}</h1>
        <p>
            <time datetime="{{.Start.Format "2006-01-02T15:04:05Z07:00"}}">{{with .When}}{{if .AllDay}}{{dateRange .Start .End "full"}}{{else if .SameDay}}{{date .Start "full"}} · {{timeRange .Start .End}}{{else}}{{date .Start "full"}}, {{time .Start}} – {{date .End "full"}}, {{time .End}}{{end}}{{end}}</time>{{if not .AllDay}} ({{.Timezone}}){{end}}
        </p>
        {{with .Location}}<p>{{.}}{{with $.Address}}<br>{{.}}{{end}}</p>{{end}}
        {{if .ImageURL}}<img src="{{.ImageURL}}" srcset="{{.ImageSrcset}}" sizes="100vw" alt="">{{end}}
        {{with .Summary}}<p>{{.}}</p>{{end}}
        <div>{{.Body}}</div>
    </article>
</main>

Types.Decl:
type APIEvent struct {
	ID       string `json:"id"`
	Slug     string `json:"slug"`
	Title    string `json:"title"`
	Summary  string `json:"summary"`
	BodyHTML string `json:"body_html,omitempty"`
	Location string `json:"location"`
	Address  string `json:"address"`
	// Start and End are in Timezone, with its offset; End is null for an
	// event without an end. For an all-day event they are the first and
	// the last day at midnight.
	Start    time.Time  `json:"start"`
	End      *time.Time `json:"end"`
	AllDay   bool       `json:"all_day"`
	Timezone string     `json:"timezone"`
	// Past is set once the event is over.
	Past bool `json:"past"`
	// URL is the event's page, null while the agenda is on no page; APIURL
	// the event in the API.
	URL       *string    `json:"url"`
	APIURL    string     `json:"api_url"`
	Image     *api.Image `json:"image"`
	UpdatedAt time.Time  `json:"updated_at"`
}

type Event struct {
	ID       string
	Title    string
	Summary  string
	Body     template.HTML
	Location string
	Address  string
	// Start and End are in Timezone; for "UTC" they are civil times (see
	// frontend.Civil). End is zero when the event has no end; for all-day
	// events it is the last day.
	Start    time.Time
	End      time.Time
	AllDay   bool
	Timezone string
	// URL is the event's page, empty when the agenda is on no page.
	URL string
	// ImageURL is the event's image as pages show it, at most media.ImageWidth
	// wide (see frontend.Frontend.Image); ImageSrcset lists smaller
	// copies for a srcset attribute, ImageWidth and ImageHeight are the
	// size of ImageURL and ImageOriginalURL is the uploaded file, for
	// downloads. All are empty when the event has no image.
	ImageURL         string
	ImageSrcset      string
	ImageOriginalURL string
	ImageWidth       int
	ImageHeight      int
}

type Info struct {
	ID string
	// Title is in the requested language, or in the first language the
	// event has when it is not translated.
	Title string
	// Start and End are in Timezone, for "UTC" as civil times (see
	// frontend.Civil); End is zero when the event has none and the last day
	// for all-day events.
	Start    time.Time
	End      time.Time
	AllDay   bool
	Timezone string
	// Published is true when visitors can see the event in the requested
	// language; URL is then its address, when the agenda is on a page.
	Published bool
	URL       string
	// Past is true once the event is over.
	Past bool
}

type ListView struct {
	Title  string
	Events []Event
	// Past is true on the list of past events, newest first. Otherwise the
	// list holds upcoming and running events, soonest first.
	Past        bool
	UpcomingURL string
	PastURL     string
}

type Service struct {
	// contains unexported fields
}
